const body = $json.body ?? $json;
const auth = $json.headers?.authorization;
const required = ['clientName', 'rfc', 'documentType', 'fiscalPeriod'];
const missing = required.filter((key) => !body[key] || typeof body[key] !== 'string');
const rfcPattern = /^[A-ZÑ&]{3,4}\d{6}[A-Z0-9]{3}$/i;
if (missing.length || !rfcPattern.test(body.rfc ?? '')) {
  return [{ json: { ok: false, statusCode: 422, response: { success: false, error: `Solicitud inválida: ${missing.join(', ') || 'RFC inválido'}` } } }];
}
// Opcional: compara auth con `Bearer ${$env.N8N_WEBHOOK_TOKEN}` cuando el secreto exista en n8n.
return [{ json: { ok: true, statusCode: 200, response: { success: true, documentId: `DOC-${Date.now()}`, status: 'processed', extractedData: { rfc: body.rfc, issuer: 'Proveedor Demo SA de CV', date: '2026-07-01', subtotal: 10000, tax: 1600, total: 11600 }, alerts: ['Revisar posible duplicado'] } } }];
